// === Normalize Excel rows from Thai headers to standard fields ===

// ---- universal space cleaner ----
function cleanSpaces(s) {
  return String(s ?? '')
    // ลบช่องว่างแปลกๆ (non-breaking, zero-width, full-width, etc.)
    .replace(/[\u00A0\u1680\u2000-\u200D\u202F\u205F\u3000\uFEFF]/g, ' ')
    // แปลง tab/newline ให้เป็น space ปกติ
    .replace(/[\t\r\n]+/g, ' ')
    // รวม space ซ้ำ
    .replace(/\s+/g, ' ')
    .trim();
}

function onlyDigits(s) {
  return String(s ?? '').replace(/\D/g, '');
}

// แปลงเลขผู้เสียภาษีให้เป็น string ตัวเลขล้วน (ถ้าสั้นกว่า 13 จะ pad)
function normVatId(v) {
  if (v === null || v === undefined || v === '') return null;
  let s = onlyDigits(v);
  if (!s) return null;

  // เคสหน่วยงานรัฐที่เป็น 0/0000000000000 จะจัดการทีหลังก็ได้
  if (/^0+$/.test(s)) return '0';

  if (s.length < 13) {
    s = s.padStart(13, '0');
  }
  return s;
}

// แปลง branch ให้เป็น string 5 หลัก
function normBranch(b) {
  if (b === null || b === undefined) return null;
  let raw = String(b).trim();
  if (!raw) return '00000'; // ไม่มี = treat เป็นสำนักงานใหญ่ก็ได้
  if (raw === 'รวม') return '00000'; // แถวสรุป หรือรวมสาขา → ไม่ใช่ใบกำกับจริง

  let s = onlyDigits(raw);
  if (!s) return '00000';
  if (s === '0') s = '0';
  return s.padStart(5, '0');
}

// แปลงจำนวนเงินให้เป็น Number (รองรับทั้ง string/มีคอมมา)
function parseAmount(val) {
  if (val === null || val === undefined || val === '') return null;
  if (typeof val === 'number' && Number.isFinite(val)) return val;
  const normalized = String(val).replace(/[^\d.\-]/g, '');
  if (!normalized) return null;
  const n = Number(normalized);
  return Number.isNaN(n) ? null : n;
}

// normalize ชื่อบริษัท
function normalizeCompanyName(name) {
  if (!name) return null;
  let s = cleanSpaces(String(name));
  s = s.replace(/[“”"']/g, '');
  s = cleanSpaces(s);
  return s || null;
}

// === main ===
const out = [];

for (const item of items) {
  const r = item.json;

  // ---- ดึงค่าจากหัวคอลัมน์ตามไฟล์ Excel นี้ ----
  const inv      = cleanSpaces(r['เลขที่ใบกำกับภาษี'] ?? '');
  const date     = cleanSpaces(r['วันที่ใบกำกับภาษี'] ?? '');
  const ref_doc  = cleanSpaces(r['เลขที่เอกสารอ้างอิง'] ?? '');
  const doc_title = cleanSpaces(r['ประเภทใบกำกับ'] ?? '');  // << เปลี่ยนจาก 'ประเภทเอกสาร' เป็น 'ประเภทใบกำกับ'
  const contact_code = cleanSpaces(r['รหัสผู้ติดต่อ'] ?? '');
  const vname   = cleanSpaces(r['ผู้ติดต่อ'] ?? '');
  const vvat    = r['เลขทะเบียนผู้เสียภาษี'] ?? '';
  const vbr     = r['สาขา/สำนักงานใหญ่'] ?? '';
  const net     = r['รายการภาษี 7%'];
  const vat     = r['ภาษีมูลค่าเพิ่ม'];
  const grand   = r['มูลค่ารวมภาษี'];
  const status  = cleanSpaces(r['สถานะ'] ?? '');

  // ข้ามแถวที่ไม่มีข้อมูลหลัก (กันเคสว่าง/บรรทัดแปลกๆ)
  if (!inv && !vvat && !vname) {
    continue;
  }

  const vendor_name   = normalizeCompanyName(vname);
  const vendor_vat_id = normVatId(vvat);
  const vendor_branch = normBranch(vbr);

  const net_amount    = parseAmount(net);
  const vat_amount    = parseAmount(vat);
  const grand_total   = parseAmount(grand);

  out.push({
    json: {
      // key หลักที่ใช้ downstream
      invoice_number: inv,
      date_raw:       date,

      vendor_name,
      vendor_vat_id,
      vendor_branch,

      net_amount,
      vat_amount,
      grand_total,

      ref_doc:       ref_doc,      
      doc_title:     doc_title || null,
      contact_code:  contact_code,  
      status_text:   status || null
    },
    pairedItem: item.pairedItem,
  });
}

return out;

/************************************************************
 * n8n Code Node: Compare Excel vs invoices (both directions)
 *
 * - Excel (normalize แล้ว) จาก node: "Code: Normalize rows"
 * - PDF/invoices จาก Postgres node: "Select rows from a table"
 *
 * ตรวจเฉพาะ 8 field:
 *  - invoice_number
 *  - date_raw
 *  - vendor_name
 *  - vendor_vat_id
 *  - vendor_branch
 *  - net_amount
 *  - vat_amount
 *  - grand_total
 *
 * fields อื่น (invoice_status, buyer_vat_info_status) = null
 *
 * ครอบคลุม 2 ฝั่ง:
 *  1) Excel → DB  (Excel มี แต่ DB อาจมี/ไม่มี)
 *  2) DB   → Excel(DB มี แต่ Excel อาจไม่มี)
 ************************************************************/

// ------------------------------------------------------
// Helpers
// ------------------------------------------------------
function cleanSpaces(s) {
  return String(s ?? '')
    .replace(/[\u00A0\u1680\u2000-\u200D\u202F\u205F\u3000\uFEFF]/g, ' ')
    .replace(/[\t\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function onlyDigits(s) {
  return String(s ?? '').replace(/\D/g, '');
}

function normVatId(v) {
  if (v == null || v === '') return null;
  let s = onlyDigits(v);
  if (!s) return null;

  // 0000000000000 → treat เป็น "0"
  if (/^0+$/.test(s)) return '0';

  return s.padStart(13, '0');
}

function normBranch(b) {
  if (b == null) return null;
  let s = onlyDigits(String(b));
  if (!s) return '00000';
  return s.padStart(5, '0');
}

function parseAmount(val) {
  if (val === null || val === undefined || val === '') return null;
  if (typeof val === 'number' && Number.isFinite(val)) return val;
  const s = String(val).replace(/[^\d.\-]/g, '');
  if (!s) return null;
  const n = Number(s);
  return Number.isNaN(n) ? null : n;
}

function sameAmount(a, b, eps = 0.01) {
  if (a == null || b == null) return false;
  const na = Number(a);
  const nb = Number(b);
  if (Number.isNaN(na) || Number.isNaN(nb)) return false;
  return Math.abs(na - nb) <= eps;
}

function normalizeCompanyName(name) {
  if (!name) return null;

  let s = cleanSpaces(String(name));   // รวม space แปลก ๆ ให้เป็น space ปกติ + trim
  s = s.replace(/[“”"']/g, '');        // ตัด quote ทิ้ง
  s = s.replace(/\u200B/g, '');        // ตัด zero-width space
  s = s.replace(/\s+/g, '');           // ลบช่องว่างทุกชนิดทั้งหมดออก

  return s || null;
}


// ------------------------------------------------------
// 1) ดึงข้อมูลจาก node อื่น
// ------------------------------------------------------

// Excel normalize แล้วจาก node "Code: Normalize rows"
// structure ที่คาดหวังต่อแถว:
// {
//   invoice_number,
//   date_raw,
//   vendor_name,
//   vendor_vat_id,
//   vendor_branch,
//   net_amount,
//   vat_amount,
//   grand_total
// }
const excelItems = $items('Code: Normalize rows', 0, 0);
const excelRows  = excelItems.map(i => i.json);

// ข้อมูล invoices จาก Postgres node "Select rows from a table"
// SELECT id, invoice_number, date_raw, vendor_name,
//        vendor_vat_id, vendor_branch,
//        net_amount, vat_amount, grand_total
// FROM   schema.invoices;
const dbItems = $items('Select rows from a table', 0, 0);
const dbRows  = dbItems.map(i => i.json);

// ------------------------------------------------------
// 2) สร้าง map สำหรับฝั่ง invoices (DB) และชุด key ของ Excel
//    key = invoice_number + vendor_vat_id + vendor_branch (normalized)
// ------------------------------------------------------
const dbMap = new Map();
const dbKeySet = new Set();   // เก็บ key ทั้งหมดของ DB
const excelKeySet = new Set(); // เก็บ key ทั้งหมดของ Excel

// เตรียม map ฝั่ง DB
for (const row of dbRows) {
  const invNo   = cleanSpaces(row.invoice_number ?? '');
  const vatId   = normVatId(row.vendor_vat_id);
  const branch  = normBranch(row.vendor_branch);

  const key = [invNo, vatId, branch].join('|');
  dbKeySet.add(key);

  if (!dbMap.has(key)) {
    dbMap.set(key, {
      ...row,
      _norm_invoice_number: invNo,
      _norm_vendor_vat_id:  vatId,
      _norm_vendor_branch:  branch,
      _norm_vendor_name:    normalizeCompanyName(row.vendor_name),
    });
  }
}

// ------------------------------------------------------
// 3) Pass 1: Excel → DB
//    - ถ้ามีใน Excel:
//        - ถ้ามีใน DB → เทียบ 8 field
//        - ถ้าไม่มีใน DB → status = null, all_ok = false, missing_in_pdf = true
// ------------------------------------------------------
const out = [];

for (let index = 0; index < excelRows.length; index++) {
  const r = excelRows[index];

  // normalize จาก Excel
  const invoice_number = cleanSpaces(r.invoice_number);
  const date_raw       = cleanSpaces(r.date_raw);
  const vendor_name    = normalizeCompanyName(r.vendor_name);
  const vendor_vat_id  = normVatId(r.vendor_vat_id);
  const vendor_branch  = normBranch(r.vendor_branch);

  const net_amount     = parseAmount(r.net_amount);
  const vat_amount     = parseAmount(r.vat_amount);
  const grand_total    = parseAmount(r.grand_total);

  // ถ้า excel แถวนี้ไม่มี key หลักเลย → ข้าม (เช่น แถว total)
  if (!invoice_number && !vendor_vat_id && !vendor_name) {
    continue;
  }

  const key = [invoice_number, vendor_vat_id, vendor_branch].join('|');
  excelKeySet.add(key);

  const inv = dbMap.get(key) || null;

  let invoice_number_status = null;
  let date_raw_status       = null;
  let vendor_name_status    = null;
  let vendor_vat_id_status  = null;
  let vendor_branch_status  = null;
  let net_amount_status     = null;
  let vat_amount_status     = null;
  let grand_total_status    = null;
  let all_ok                = false;

  if (inv) {
    // มีใน DB → เทียบ 8 field
    invoice_number_status = (invoice_number === inv._norm_invoice_number);
    date_raw_status       = (date_raw       === cleanSpaces(inv.date_raw ?? ''));
    vendor_name_status    = (vendor_name    === inv._norm_vendor_name);
    vendor_vat_id_status  = (vendor_vat_id  === inv._norm_vendor_vat_id);
    vendor_branch_status  = (vendor_branch  === inv._norm_vendor_branch);

    net_amount_status     = sameAmount(net_amount,  inv.net_amount);
    vat_amount_status     = sameAmount(vat_amount,  inv.vat_amount);
    grand_total_status    = sameAmount(grand_total, inv.grand_total);

    const flags = [
      invoice_number_status,
      date_raw_status,
      vendor_name_status,
      vendor_vat_id_status,
      vendor_branch_status,
      net_amount_status,
      vat_amount_status,
      grand_total_status,
    ];

    all_ok = flags.every(v => v === true);
  } else {
    // ไม่มีใน DB → ถือว่า "มีใน Excel แต่ไม่มีใน PDF"
    // status = null, all_ok = false, flag missing_in_pdf = true
    all_ok = false;
  }

  out.push({
    json: {
      source: 'excel',          // เอาไว้ debug/UI
      missing_in_pdf: !inv,     // true ถ้า Excel มีแต่ DB ไม่มี
      missing_in_excel: false,  // เฉพาะฝั่งนี้ไม่มีเคส

      invoice_id: inv ? inv.id : null,

      invoice_number,
      vendor_vat_id,
      vendor_branch,

      // 8 field statuses
      invoice_number_status,
      date_raw_status,
      vendor_name_status,
      vendor_vat_id_status,
      vendor_branch_status,
      net_amount_status,
      vat_amount_status,
      grand_total_status,

      // ฟิลด์สถานะที่ไม่ใช้ → null
      invoice_status:         null,
      buyer_vat_info_status:  null,

      all_ok,
    },
    pairedItem: excelItems[index]?.pairedItem,
  });
}

// ------------------------------------------------------
// 4) Pass 2: DB → Excel
//    หาใบกำกับที่ "มีใน PDF(invoices) แต่ไม่มีใน Excel"
// ------------------------------------------------------
for (const db of dbRows) {
  const invNo   = cleanSpaces(db.invoice_number ?? '');
  const vatId   = normVatId(db.vendor_vat_id);
  const branch  = normBranch(db.vendor_branch);

  const key = [invNo, vatId, branch].join('|');

  // ถ้า key นี้ไม่มีใน Excel → คือ "มีใน PDF แต่ไม่มีใน Excel"
  if (!excelKeySet.has(key)) {
    out.push({
      json: {
        source: 'pdf',
        missing_in_pdf: false,
        missing_in_excel: true,

        invoice_id: db.id,

        invoice_number: invNo,
        vendor_vat_id:  vatId,
        vendor_branch:  branch,

        // ไม่มี Excel ให้เทียบ → status = null ทั้งหมด
        invoice_number_status: null,
        date_raw_status:       null,
        vendor_name_status:    null,
        vendor_vat_id_status:  null,
        vendor_branch_status:  null,
        net_amount_status:     null,
        vat_amount_status:     null,
        grand_total_status:    null,

        invoice_status:         null,
        buyer_vat_info_status:  null,

        all_ok: false, // ชัดเจนว่าไม่ครบคู่
      },
      // ฝั่งนี้ไม่ได้มาจาก Excel → ไม่มี pairedItem
    });
  }
}

return out;

const items = $input.all();

// ดึงชื่อโฟลเดอร์สุดท้าย เช่น "/files/EXAM/" → "EXAM"
function extractFolderName(path) {
  if (!path) return "default";
  const parts = String(path).split('/');
  for (let i = parts.length - 1; i >= 0; i--) {
    if (parts[i] && parts[i].trim() !== "" && !parts[i].includes('*')) {
      return parts[i];
    }
  }
  return "default";
}

return items.map(item => {
  const body = item.json.body || {};

  // ❗ ใช้ path จาก body.schema แทน excelFolder
  const schemaPath = body.schema;        // เช่น "/files/EXAM/"

  // ดึง folder สุดท้าย → "EXAM"
  const folderName = extractFolderName(schemaPath);

  // normalize unicode
  const normalized = folderName.normalize("NFC");

  // แปลงเป็น hex 16 ตัว
  const hashedSchema = "s_" + Buffer.from(normalized).toString("hex").slice(0, 16);

  return {
    json: {
      ...item.json,
      body: {
        ...body,
        schema: hashedSchema,   // เขียนทับ schema เดิม
      },
    },
  };
});

const items = $input.all();

// update เฉพาะ items ที่มี invoice_number + vendor_vat_id + vendor_branch ครบ
return items.filter(i => {
  const j = i.json;
  return (
    j.invoice_number &&
    String(j.invoice_number).trim() !== "" &&
    j.vendor_vat_id &&
    j.vendor_branch
  );
});
